const email = $('Get Unread Invoice Emails').item.json;
const pdfText = $json.text || '';
const subject = email.subject || '';
const emailBody = email.text || (email.html || '').replace(/<[^>]+>/g, ' ');
const content = subject + '\n' + pdfText + '\n' + emailBody;

// Invoice number: "Invoice #123", "Invoice No: 123", "Invoice number INV-123", "Inv. 123"
let invoiceNumber = null;
const invMatch = content.match(/inv(?:oice)?\.?\s*(?:number|num|no\.?|#|:)?\s*[:#]?\s*([A-Z0-9][A-Z0-9\-\/]{1,30})/i);
if (invMatch) invoiceNumber = invMatch[1];

// Amount: look near amount/total/due keywords first, then any currency value
let amount = null;
let currency = null;
const amtRegex = /(?:total|amount|sum|due|balance)[^0-9$€£₪]{0,30}([$€£₪])?\s*([0-9][0-9.,\s]*[0-9]|[0-9])\s*(USD|EUR|GBP|ILS|NIS)?/i;
const anyCurrency = /([$€£₪])\s*([0-9][0-9.,]*[0-9]|[0-9])|([0-9][0-9.,]*[0-9])\s*(USD|EUR|GBP|ILS|NIS)/i;
let m = content.match(amtRegex);
let raw = null;
if (m) { raw = m[2]; currency = m[1] || m[3] || null; }
else {
  const a = content.match(anyCurrency);
  if (a) { raw = a[2] || a[3]; currency = a[1] || a[4] || null; }
}
if (raw) {
  let s = raw.replace(/\s/g, '');
  const lastComma = s.lastIndexOf(',');
  const lastDot = s.lastIndexOf('.');
  if (lastComma > lastDot) {
    // European format 3.400,00 or 1250,50
    s = s.replace(/\./g, '').replace(',', '.');
  } else {
    s = s.replace(/,/g, '');
  }
  const n = parseFloat(s);
  amount = isNaN(n) ? null : n;
}
const symbolMap = { '$': 'USD', '€': 'EUR', '£': 'GBP', '₪': 'ILS', 'NIS': 'ILS' };
if (currency) currency = symbolMap[currency.toUpperCase()] || symbolMap[currency] || currency.toUpperCase();

const sender = (email.from && email.from.value && email.from.value[0] && email.from.value[0].address) || '';

return {
  json: {
    messageId: email.id,
    invoiceNumber: invoiceNumber,
    amount: amount,
    currency: currency,
    subject: subject,
    sender: sender,
    receivedAt: email.date || null,
    processedAt: new Date().toISOString(),
    parsed: Boolean(invoiceNumber && amount !== null),
  },
};
